'use client';
import React from 'react';

interface MoodChartProps {
  totalCatatan: number;
  statistikSuasana: { [key: string]: number };
  wawasanBulanan: { [key: string]: { total: number; suasanaList: string[] } };
  emojiSuasanaMap: { [key: string]: string };
  isDarkMode: boolean;
}

export default function MoodChart({ totalCatatan, statistikSuasana, wawasanBulanan, emojiSuasanaMap, isDarkMode }: MoodChartProps) {
  if (totalCatatan === 0) return null;

  return (
    <div className="space-y-4">
      <div className={`p-4 rounded-2xl border space-y-3 ${
        isDarkMode ? 'bg-black/20 border-[#7A8A76]/15' : 'bg-white/60 border-[#8A9A86]/15'
      }`}>
        <div className="flex justify-between items-center">
          <span className={`text-[10px] font-semibold uppercase tracking-wider block ${isDarkMode ? 'text-[#A2B59F]' : 'text-[#6E7D6A]'}`}>
            Grafik Tren Suasana Hati
          </span>
          <span className="text-[10px] opacity-50 font-mono">{totalCatatan} Total Jejak</span>
        </div>

        <div className="space-y-2 pt-1">
          {Object.entries(statistikSuasana).map(([suasana, jumlah], idx) => {
            const persentase = Math.round((jumlah / totalCatatan) * 100);
            const emoji = emojiSuasanaMap[suasana] || "🍃";
            return (
              <div key={idx} className="space-y-1">
                <div className="flex justify-between items-center text-[10px]">
                  <span className={`font-medium flex items-center gap-1 ${isDarkMode ? 'text-[#C5CDC2]' : 'text-[#5F6E5B]'}`}>
                    <span>{emoji}</span>
                    <span>{suasana}</span>
                  </span>
                  <span className="opacity-60 font-mono">{jumlah} ({persentase}%)</span>
                </div>
                <div className={`w-full h-1.5 rounded-full overflow-hidden ${isDarkMode ? 'bg-white/5' : 'bg-[#8A9A86]/15'}`}>
                  <div 
                    className="h-full bg-[#7A8A76] rounded-full transition-all duration-500" 
                    style={{ width: `${persentase}%` }}
                  />
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div className={`p-4 rounded-2xl border space-y-3 ${
        isDarkMode ? 'bg-black/20 border-[#7A8A76]/15' : 'bg-white/60 border-[#8A9A86]/15'
      }`}>
        <div className="flex justify-between items-center">
          <span className={`text-[10px] font-semibold uppercase tracking-wider block ${isDarkMode ? 'text-[#A2B59F]' : 'text-[#6E7D6A]'}`}>
            📊 Wawasan Jurnal Bulanan
          </span>
        </div>
        <div className="space-y-2 pt-1 text-[11px]">
          {Object.entries(wawasanBulanan).map(([bulan, dataBulan], idx) => (
            <div key={idx} className={`p-2.5 rounded-xl border flex justify-between items-center ${
              isDarkMode ? 'border-[#7A8A76]/20 bg-white/5' : 'border-[#8A9A86]/20 bg-white/40'
            }`}>
              <span className="font-medium">{bulan}</span>
              <span className="opacity-70 font-mono">{dataBulan.total} Catatan Refleksi</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}